COPY (SELECT objectid, uwi, source, glj_well_id, country, province_state, well_name, plot_symbol, profile_type, construction_method, orig_fid, case when ST_CoordDim(shape) > 2 then st_astext(ST_Force3D(replace(st_astext(shape)::text,' NaN)',' 0.00000000)'))) else st_astext(ST_Force2D(replace(st_astext(shape)::text,' NaN)',' 0.00000000)'))) end as shape FROM pgsdeprod_prod_wld.glj_wld_well_bh) TO STDOUT DELIMITER ',' CSV; -- FILE:DATAPATH/pgsdeprod_prod_wld.glj_wld_well_bh.csv
COPY (SELECT objectid, uwi, survey_id, province_state, x_uwi_display, source, profile_type, current_status, td_strat_age, td_strat_unit_id, load_date, case when ST_CoordDim(shape) > 2 then st_astext(ST_Force3D(replace(st_astext(shape)::text,' NaN)',' 0.00000000)'))) else st_astext(ST_Force2D(replace(st_astext(shape)::text,' NaN)',' 0.00000000)'))) end as shape FROM pgsdeprod_prod_can.glj_well_dir_srvy_loc) TO STDOUT DELIMITER ',' CSV; -- FILE:DATAPATH/pgsdeprod_prod_can.glj_well_dir_srvy_loc.csv
COPY (SELECT objectid, acqtech, credate, revdate, accuracy, provider, specvers, alcode, language1, name1, language2, name2, language3, name3, language4, name4, language5, name5, jur1, jur2, altype, webref, case when ST_CoordDim(shape) > 2 then st_astext(ST_Force3D(replace(st_astext(shape)::text,' NaN)',' 0.00000000)'))) else st_astext(ST_Force2D(replace(st_astext(shape)::text,' NaN)',' 0.00000000)'))) end as shape FROM pgsdeprod_prod_can.geobase_aboriginal_lands) TO STDOUT DELIMITER ',' CSV; -- FILE:DATAPATH/pgsdeprod_prod_can.geobase_aboriginal_lands.csv
